(window.LADDER_CARDS["43·crypt"]=window.LADDER_CARDS["43·crypt"]||[]).push(
 {"u":"43·crypt.1.1","q":"Why must the prime p be larger than both the secret and the number of people? What does each person hold, and where on the curve is the secret?","a":"The secret must be an hour of the clock, and the people’s places 1, 2, …, 5 must be different hours, none of them 0; person i holds the pair (i, f(i)), a point of the dealer’s curve f(x) ≡ s + a₁x + a₂x² of degree at most 2; the secret is f(0), where the curve meets x = 0","w":["So that the powers are fast; each person holds the whole curve; the secret is the curve’s highest point","So that p has many factors; each person holds a₁ or a₂; the secret is f(1)","So that the curve has no roots; each person holds one digit of the secret; the secret is the sum of the shares"],"why":"On the clock of 101 with s = 57: the shares are 39, 60, 19, 17, 54."},
 {"u":"43·crypt.2.1","q":"Why can two curves of degree at most 2 not agree at three hours unless they are equal? Why does building ℓ₁ need the clock to be prime?","a":"Their difference has degree at most 2 and three roots, and by the few-roots technique a nonzero curve of degree 2 on a prime clock has at most 2 roots, so the difference is 0; ℓ₁ divides by (x₁ − x₂)(x₁ − x₃), which is a unit on a prime clock since the hours differ; on the clock of 12, 2 has no undoing, and three points can fit two curves or none","w":["Because curves of degree 2 never cross; ℓ₁ needs a prime clock so that the points are far apart","Because three points lie on one straight line; ℓ₁ needs a prime clock because the secret is prime","Because the difference has degree 3; ℓ₁ needs a prime clock so that the curve has a root"],"why":"So three shares fix the curve, and its value at 0."},
 {"u":"43·crypt.3.1","q":"Why are the weights the values at 0 of the three pieces? Why do the weights depend only on which hours came, and not on the shares?","a":"The holders need only f(0), and f ≡ y₁ℓ₁ + y₂ℓ₂ + y₃ℓ₃, so f(0) ≡ y₁ℓ₁(0) + y₂ℓ₂(0) + y₃ℓ₃(0); each piece ℓₖ is built from the hours x₁, x₂, x₃ alone, as w₁ ≡ x₂x₃/((x₁ − x₂)(x₁ − x₃)), with the shares yₖ entering only as the multipliers","w":["The weights are the shares themselves; they depend on the hours because the shares are secret","The weights are the values at 1 of the pieces; they depend on the secret, not the hours","The weights are all ⅓, an average; they depend on nothing"],"why":"For holders 1, 3, 5: 557 · 8⁻¹ ≡ 52 · 38 ≡ 57 (mod 101)."},
 {"u":"43·crypt.4.1","q":"What does the two-say-nothing technique say? Why does the count of dealings that fit two shares come out the same for every possible secret?","a":"For any two shares at different hours and any hour s′, exactly one curve of degree at most 2 passes through both shares and has the value s′ at 0, so every secret is equally likely given two shares; the dealer’s choice (a₁, a₂) is one of p², all equally likely, and for each s′ the three points (0, s′) and the two shares fix exactly one of them, by the three-points-fix technique","w":["Two shares fix the curve, so two holders know the secret; the count is 0 for every wrong secret","Two shares rule out all but ten secrets; the count differs with the secret’s size","Two shares give the secret with chance ½; the count is the same because p is odd"],"why":"Through (1, 39) and (2, 60) pass curves with secrets 0, 57 and 100 alike."},
 {"u":"43·crypt.5.1","q":"Why would the ordinary numbers leak hints about the secret? Why must the dealer choose a₂ at random and never fix it at 0?","a":"Sizes leak: on the clock every hour is as likely, and off it they are not; and with a₂ = 0 the curve is a straight line, and two shares fix it","w":["The ordinary numbers leak nothing; and a₂ = 0 makes the curve safer","Because the ordinary numbers have no primes; and a₂ = 0 makes every share equal","Because sums are slow off the clock; and a₂ = 0 gives a curve of degree 3"],"why":"Both are rows of the step’s Moves to Watch Out For."});
/* end phase F und_r43 */
