(window.LADDER_CARDS=window.LADDER_CARDS||{})["20·crypt2"]=[{"q": "A cipher that encrypts fixed-length chunks of bits. What is it called?", "a": "a block cipher", "w": ["a stream cipher", "a hash function", "a public-key cipher"], "why": "For each key, a permutation of all blocks."}, {"q": "For one key, what must a block cipher’s encryption be on the set of blocks?", "a": "a permutation (a bijection)", "w": ["any function", "a constant map", "a two-to-one map"], "why": "Otherwise two blocks could not be told apart after decryption."}, {"q": "How many permutations of the 2⁴ = 16 four-bit blocks are there?", "a": "16!", "w": ["16", "2¹⁶", "4!"], "why": "Every order of the 16 blocks."}, {"q": "1010 ⊕ 0110?", "a": "1100", "w": ["10000", "0010", "1110"], "why": "XOR: add each place with no carry."}, {"q": "(L, R) ↦ (R, L ⊕ f(R)). What is this round structure called?", "a": "a Feistel round", "w": ["a substitution box", "a key schedule", "an S-P network"], "why": "Horst Feistel, IBM, early 1970s."}, {"q": "Must f be invertible for a Feistel round to be invertible?", "a": "no: the round can be undone for any f", "w": ["yes, always", "only if f is linear", "only for 64-bit blocks"], "why": "Adding f(R) twice gives back L."}, {"q": "How is a Feistel cipher of r rounds decrypted?", "a": "by the same rounds with the round keys in reverse order", "w": ["by the same rounds in the same key order", "by inverting f in each round", "by a different algorithm entirely"], "why": "Undo in reverse: the last round first."}, {"q": "Changing one input bit changes about half the output bits. What is this property called?", "a": "the avalanche effect", "w": ["the birthday effect", "diffusion failure", "key reuse"], "why": "Stack rounds until it holds."}, {"q": "Each block encrypted on its own with the same key, so equal blocks give equal outputs. What mode is it?", "a": "ECB (electronic codebook)", "w": ["CBC", "CTR", "GCM"], "why": "Patterns in the message show through."}, {"q": "cᵢ = E(pᵢ ⊕ cᵢ₋₁) with a random first block v. What mode is this, and what is v called?", "a": "CBC mode; the initialisation vector", "w": ["ECB mode; the round key", "CTR mode; the nonce counter", "CBC mode; the master key"], "why": "Equal plain blocks no longer give equal outputs."}];
